// The old generateTest() called the Supabase edge function `generate-test` (OpenAI / DeepSeek +
// text-embedding-004, shut down 14 Jan 2026). No caller remained; removed in Gate 2 #10. Papers are generated by
// the backend (/api/v1/test-generator/generate-frontend).

export function downloadTestFile(generatedTest: string, subject: string) {
  const element = document.createElement("a");
  const file = new Blob([generatedTest], {type: 'text/plain'});
  element.href = URL.createObjectURL(file);
  element.download = `test-${subject || 'generated'}-${new Date().toISOString().split('T')[0]}.txt`;
  document.body.appendChild(element);
  element.click();
  document.body.removeChild(element);
}
